#!/usr/bin/env python3
"""Upstream #2642 (98 native task / mesh pipelines an iPhone 17 built at their first draw: night, Goron area, a fairy fountain), as it lands on
v3-x9: 95 of its 98 M rows are already in our pso_manifest.tsv, so this appends the other 3 with a comment line.
Run from the repo root: python3 scripts/oot_iphone/pso2642.py"""
import pathlib, sys
p = pathlib.Path("dm/games/0400486024DEC000/pso_manifest.tsv"); t = p.read_text()
ROWS = ['M	a5288d0a6c4971fd_b	', 'M	a5288d0a6c4971fd_b	', 'M	a5288d0a6c4971fd_b	']
have = set(t.split("\n"))
add = [r for r in ROWS if r not in have]
if not add: sys.exit("   already in")
if not t.endswith("\n"): t += "\n"
t += "# The last %d M rows: from upstream #2642 (an iPhone 17's pso_user.tsv on v131072), the ones this list lacked\n" % len(add)
t += "\n".join(add) + "\n"
p.write_text(t)
print("   pso_manifest.tsv: %d task / mesh pipeline rows from #2642 appended (pso2642.py)" % len(add))
